import{_ as o,o as t,c as d,a2 as r}from"./chunks/framework.BZO4qERu.js";const h=JSON.parse('{"title":"视频生成提供方","description":"","frontmatter":{},"headers":[],"relativePath":"zh/integrations/providers/video.md","filePath":"zh/integrations/providers/video.md","lastUpdated":1790952322000}'),a={name:"zh/integrations/providers/video.md"};function n(s,e,c,i,l,g){return t(),d("div",null,[...e[0]||(e[0]=[r('<h1 id="视频生成提供方" tabindex="-1">视频生成提供方 <a class="header-anchor" href="#视频生成提供方" aria-label="Permalink to &quot;视频生成提供方&quot;">​</a></h1><p>Bot 靠 <code>generate_video</code> 工具生成视频。要用上它，两步缺一不可：</p><ol><li>在 <strong>设置 → 集成 → Video</strong> 里配好<strong>视频提供方</strong>和至少一个视频模型；</li><li>在 <strong>Bot 设置 → 多媒体</strong> 里给 Bot 选一个<strong>视频生成模型</strong>。</li></ol><p>没选视频模型的 Bot 根本不会拿到 <code>generate_video</code> 这个工具。</p><hr><h2 id="支持的提供方" tabindex="-1">支持的提供方 <a class="header-anchor" href="#支持的提供方" aria-label="Permalink to &quot;支持的提供方&quot;">​</a></h2><table tabindex="0"><thead><tr><th>提供方</th><th>Client Type</th><th>默认 Base URL</th></tr></thead><tbody><tr><td><strong>OpenRouter</strong></td><td><code>openrouter-video</code></td><td><code>https://openrouter.ai/api</code></td></tr><tr><td><strong>ModelArk（BytePlus）</strong></td><td><code>modelark-video</code></td><td><code>https://ark.ap-southeast.bytepluses.com/api/v3</code></td></tr><tr><td><strong>火山引擎（Ark）</strong></td><td><code>volcengine-video</code></td><td><code>https://ark.cn-beijing.volces.com/api/v3</code></td></tr></tbody></table><p>都只要填 <strong>API Key</strong>；<strong>Base URL</strong> 不填就用默认值。</p><p>模板里带好了当前的 Seedance / Veo / 豆包 Seedance 预设模型：</p><ul><li><strong>OpenRouter</strong>：<code>bytedance/seedance-2.0</code>、<code>google/veo-3.1-fast</code>、<code>google/veo-3.1-lite</code></li><li><strong>ModelArk</strong>：<code>dreamina-seedance-2-0-260128</code>、<code>dreamina-seedance-2-0-fast-260128</code>、<code>dreamina-seedance-2-5</code></li><li><strong>火山引擎</strong>：<code>doubao-seedance-2-0-260128</code>、<code>doubao-seedance-2-0-fast-260128</code>、<code>doubao-seedance-2-5</code></li></ul><p>OpenRouter 支持 <strong>Import Models</strong> 在线拉模型列表；ModelArk 和火山引擎没有在线列表，模型来自模板或手动添加。</p><hr><h2 id="配置步骤" tabindex="-1">配置步骤 <a class="header-anchor" href="#配置步骤" aria-label="Permalink to &quot;配置步骤&quot;">​</a></h2><ol><li>打开 <strong>设置 → 集成 → Video</strong>。</li><li>从模板列表里加一个提供方（OpenRouter / ModelArk / 火山引擎）。</li><li>填 API Key，非默认接入点才需要改 Base URL，保存。</li><li>看 <strong>Video Models</strong> 区：列表空的话从提供方导入或手动加一个。</li><li>去 Bot <strong>设置 → 多媒体</strong>，选上<strong>视频生成模型</strong>。</li></ol><hr><h2 id="bot-怎么用" tabindex="-1">Bot 怎么用 <a class="header-anchor" href="#bot-怎么用" aria-label="Permalink to &quot;Bot 怎么用&quot;">​</a></h2><p>直接跟 Bot 说&quot;给我生成一个 xx 的视频&quot;就行。背后发生的事：</p><ul><li><code>generate_video</code> 是<strong>后台任务</strong>，立刻返回 task ID；生成通常要几分钟，Bot 自己用后台任务工具盯进度。</li><li>参数除了 <code>prompt</code>，还有可选的 <code>duration_seconds</code>、<code>resolution</code>（<code>720p</code>/<code>1080p</code>）、<code>aspect_ratio</code>（<code>16:9</code>、<code>9:16</code>、<code>1:1</code>）、提供方专属的 <code>size</code>、<code>generate_audio</code>。</li><li>成片下载到 Bot workspace 的 <code>/data/generated-videos/&lt;task_id&gt;.mp4</code>（也可能是 <code>.webm</code>/<code>.mov</code>，看提供方输出）。</li><li>视频<strong>不会自动发出去</strong>——Bot 以消息附件形式交付，你也可以去 workspace 的 <strong>Files</strong> tab 拿。</li></ul><p>生成完成时如果 workspace 不可达，任务照样算完成，会带 warning 和提供方的输出 URL，只是没存盘。</p><hr><h2 id="相关页面" tabindex="-1">相关页面 <a class="header-anchor" href="#相关页面" aria-label="Permalink to &quot;相关页面&quot;">​</a></h2><ul><li><a href="./llm.html">模型服务商与模型</a></li><li><a href="./../../guides/container.html">Workspace</a></li></ul>',22)])])}const u=o(a,[["render",n]]);export{h as __pageData,u as default};
